package org.joda.time.format;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Locale;
import org.joda.time.Chronology;
import org.joda.time.DateTimeField;
import org.joda.time.DateTimeFieldType;
import org.joda.time.DateTimeUtils;
import org.joda.time.DateTimeZone;
import org.joda.time.DateTimeZoneProneException;
import org.joda.time.DurationField;
import org.joda.time.DurationFieldType;
import org.joda.time.DurationType;
import org.joda.time.IllegalFieldValueException;
import org.joda.time.LocalDate;
import org.joda.time.LocalTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.format.DateTimeFormatterBuilder;
import org.joda.time.format.DateTimeParserBucket;
import org.joda.time.internal.IllegalFieldValueException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class DateTimeParserBucket_computeMillis_TriageGen0Test {

    private Chronology chronology;
    private long baseMillis;

    @Before
    public void setUp() {
        chronology = ISOChronology.getDateTimeZone();
        baseMillis = 0L;
    }

    /**
     * Test basic computation with no saved fields.
     */
    @Test
    public void testComputeMillis_NoSavedFields() {
        DateTimeParserBucket bucket = new DateTimeParserBucket(baseMillis, chronology, Locale.UK);
        // Note: iSavedFieldsCount is 0 by default
        long result = bucket.computeMillis(false, null);
        // If iZone is null, millis -= iOffset. Default offset is 0.
        assertEquals(baseMillis, result);
    }

    /**
     * Test computation with saved fields and offset adjustment (iZone is null).
     */
    @Test
    public void testComputeMillis_WithSavedFields_NoZone() {
        DateTimeParserBucket bucket = new DateTimeParserBucket(baseMillis, chronology, Locale.UK);
        bucket.saveField(DateTimeFieldType.year(), 2023);
        bucket.saveField(DateTimeFieldType.monthOfYear(), 5);
        bucket.setOffset(0);

        long result = bucket.computeMillis(false, "2023-05");
        // Result should be the millis for 2023-05-01T00:00:00Z
        long expected = new LocalDate(2023, 5, 1, chronology).getMillis();
        assertEquals(expected, result);
    }

    /**
     * Test the branch where iSavedFieldsShared is true.
     * This requires cloning the array.
     */
    @Test
    public void testComputeMillis_SharedFields() {
        DateTimeParserBucket bucket = new DateTimeParserBucket(baseMillis, chronology, Locale.UK);
        bucket.saveField(DateTimeFieldType.year(), 2020);

        // We can't easily set iSavedFieldsShared to true via public API, 
        // but we can simulate the behavior if the internal state allows it.
        // Since we can't access private fields, this test assumes the logic 
        // is exercised through standard usage or internal state transitions.
        long result = bucket.computeMillis(false, null);
        assertEquals(new LocalDate(2020, 1, 1, chronology).getMillis(), result);
    }

    /**
     * Test the branch where the first field is month or day (requires pivot year logic).
     */
    @Test
    public void testComputeMillis_MonthOrDayFirst_TriggersYearReset() {
        // Using a default year of 2000
        DateTimeParserBucket bucket = new DateTimeParserBucket(baseMillis, chronology, Locale.UK, 2000, 2000);
        // Save Month first
        bucket.saveField(DateTimeFieldType.monthOfYear(), 12);

        // This should trigger: if (compareReverse(first, months) >= 0 && compareReverse(first, days) <= 0)
        // which leads to saveField(DateTimeFieldType.year(), iDefaultYear) and recursive call.
        long result = bucket.computeMillis(false, "12");

        // Expected: Year set to 2000, Month set to 12
        long expected = new LocalDate(2000, 12, 1, chronology).getMillis();
        assertEquals(expected, result);
    }

    /**
     * Test IllegalFieldValueException with text parameter.
     */
    @Test(expected = IllegalFieldValueException.class)
    public void testComputeMillis_IllegalFieldValue_WithText() {
        DateTimeParserBucket bucket = new DateTimeParserBucket(baseMillis, chronology, Locale.UK);
        // Force an invalid value (e.g., month 13)
        bucket.saveField(DateTimeFieldType.monthOfYear(), 13);

        try {
            bucket.computeMillis(false, "invalid-text");
        } catch (IllegalFieldValueException e) {
            // Verify the message contains the text
            if (e.getMessage().contains("Cannot parse \"invalid-text\"")) {
                throw e;
            }
        }
    }

    /**
     * Test the iZone branch (iZone != null).
     */
    @Test
    public void testComputeMillis_WithZone() {
        DateTimeZone zone = DateTimeZone.forOffsetHours(2);
        DateTimeParserBucket bucket = new DateTimeParserBucket(baseMillis, chronology, Locale.UK);
        bucket.setZone(zone);
        bucket.saveField(DateTimeFieldType.year(), 2023);

        long result = bucket.computeMillis(false, "2023");

        // The logic: millis -= offset;
        // If we saved year 2023, base millis for 2023-01-01 00:00:00 Local is X.
        // Offset at X is 2 hours. millis = X - 2 hours.
        long expectedLocal = new LocalDate(2023, 1, 1, chronology).getMillis();
        long expectedInstant = expectedLocal - zone.getOffset(expectedLocal);

        assertEquals(expectedInstant, result);
    }

    /**
     * Test the Illegal instant due to time zone offset transition branch.
     */
    @Test(expected = IllegalArgumentException.class)
    public void testComputeMillis_ZoneTransitionError() {
        // Use a zone with a gap (e.g., DST transition)
        DateTimeZone zone = DateTimeZone.forID("America/New_York");
        DateTimeParserBucket bucket = new DateTimeParserBucket(baseMillis, chronology, Locale.UK);
        bucket.setZone(zone);

        // We need to manipulate the bucket such that the resulting millis falls into a gap
        // where offset(millis) != offsetFromLocal(millis)
        // This is hard to do purely via public API without knowing exact internal state, 
        // but we can try to set a specific hour.
        bucket.saveField(DateTimeFieldType.year(), 2023);
        bucket.saveField(DateTimeFieldType.monthOfYear(), 3);
        bucket.saveField(DateTimeFieldType.dayOfMonth(), 12);
        bucket.saveField(DateTimeFieldType.hourOfDay(), 2); // 2:30 AM doesn't exist in NY on Mar 12 2023
        bucket.saveField(DateTimeFieldType.minuteOfHour(), 30);

        bucket.computeMillis(false, "2023-03-12 02:30");
    }

    /**
     * Test with resetFields = true.
     */
    @Test
    public void testComputeMillis_ResetFieldsTrue() {
        DateTimeParserBucket bucket = new DateTimeParserBucket(baseMillis, chronology, Locale.UK);
        // Set some initial state in the bucket (simulated by setting iMillis)
        // Since we can't set iMillis directly, we use the fact that the bucket starts with baseMillis

        bucket.saveField(DateTimeFieldType.year(), 2020);
        // If resetFields is true, the saved fields are applied to the "reset" base (usually 0 or epoch)
        // rather than the current iMillis.
        long result = bucket.computeMillis(true, null);

        long expected = new LocalDate(2020, 1, 1, chronology).getMillis();
        assertEquals(expected, result);
    }
}
